import * as Icons from '@adobe-commerce/elsie/icons';
import { Icon } from './Icon';

const iconNames = Object.keys(Icons);

export const IconsList = iconNames.reduce(
  (acc, name) => {
    acc[name] = <Icon key={name} source={Icons[name]} size="24" stroke="1" />;
    return acc;
  },
  { none: null }
);
